import {areas,catalog,activityTitle,entriesFor} from './catalog.mjs';
import {languages} from './languages.mjs';
import {disciplines} from './disciplines.mjs';
import {stages} from './logic.mjs';
const icons=['M8 10h16v13H8z M12 6h16v13','M8 8h6v6H8z M21 8h6v6h-6z M8 21h6v6H8z M21 21h6v6h-6z','M14 6v10L7 27h22L22 16V6 M12 6h12','M7 25L23 9l5 5-16 16H7z','M14 8h12v12H14z M9 14H6v14h14v-3','M8 12a5 5 0 0 1 10-1a5 5 0 0 1 10 1q0 7-10 15Q8 19 8 12z','M18 29V11 M18 19Q6 19 8 8q10 0 10 11 M18 15Q28 15 28 5q-10 0-10 10','M6 7h24v18H18l-7 5v-5H6z M11 13h14 M11 19h9'];
const icon=i=>`<svg viewBox="0 0 36 36" aria-hidden="true" class="dashboard-icon"><path d="${icons[i%icons.length]}" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/></svg>`;
const age=a=>a.age||stages.find(s=>s.id===a.stage)?.label||a.label;
const studioGroups=[
 {id:'science',title:'Observar y comparar · Ciencias',routes:[
  ['7y:biology-lab','Comparar plantas y entorno','9–12 años · construye una comparación · registros ficticios',true],
  ['7y:chemistry-lab','Construir modelos de sustancias','9–12 años · fichas simbólicas · sin mezclas reales',true],
  ['7y:balance','Explorar una balanza','9–12 años · predice y mueve · modelo ideal',true],
  ['7y:extra','Elegir qué comparar','9–12 años · registros ficticios',false]
 ]},
 {id:'create',title:'Crear y comunicar',routes:[
  ['7y:composition','Crear un cartel','9–12 años · varias soluciones · deshacer',true],
  ['5y:extra','Crear un mensaje','6–8 años · con adulto · revisa el camino',false]
 ]},
 {id:'reason',title:'Cantidades, reglas y razones',routes:[
  ['5y:number-parts','Un número, varias formas','6–8 años · con adulto · repartir, comparar y deshacer',true],
  ['3y:quantity','Repartir una para cada cuenco','3–5 años · fichas grandes · ayuda opcional',true],
  ['3y:extra','Construir patrones','3–5 años · con adulto · cambia la regla',false],
  ['12y:arguments','Construir un argumento','13–18 años · datos ficticios · revisar conclusiones',true]
 ]},
 {id:'adult',title:'Acompañar fuera de pantalla',routes:[
  ['18m:original','Un turno que puede cambiar','Guía solo para el adulto · 18–23 meses · juego fuera de pantalla',false],
  ['2y:original','Una historia, dos maneras','Guía solo para el adulto · 24–35 meses · juego fuera de pantalla',false]
 ]}
];
function studioMarkup(){
 return `<section class="dashboard-studios" aria-labelledby="dashboard-studios"><h2 id="dashboard-studios" tabindex="-1">Talleres y guías para explorar</h2><p>Elige qué te apetece explorar y revisa la edad orientativa. Cada tarjeta indica cómo llegar al taller; puedes parar cuando quieras.</p><div class="dashboard-studio-groups">${studioGroups.map(group=>`<section class="dashboard-studio-group" aria-labelledby="dashboard-studio-${group.id}"><h3 id="dashboard-studio-${group.id}">${group.title}</h3><div class="dashboard-result-grid">${group.routes.map(([key,title,note,direct])=>`<button type="button" class="dashboard-card" data-dashboard-route="${key}"><strong>${title}</strong><span>${note}</span><span class="dashboard-studio-entry">${direct?'Abre la guía del taller':key==='18m:original'?'Abre la guía del adulto':key==='2y:original'?'Abre la guía; después, elige la historia':'Abre los ejemplos; después, elige el taller'}</span></button>`).join('')}</div></section>`).join('')}</div></section>`;
}
export function dashboardMarkup(band){
 const pick=band?entriesFor(band)[0]:null;
 return `<section class="dashboard" aria-label="Mapa de actividades y funciones"><nav class="dashboard-jumps" aria-label="Accesos del inicio"><button type="button" data-dashboard-jump="dashboard-areas">Áreas</button><button type="button" data-dashboard-jump="dashboard-languages">Idiomas y voz</button><button type="button" data-dashboard-games>Juegos</button><button type="button" data-dashboard-jump="dashboard-tools">Ayuda y progreso</button></nav><div class="dashboard-stage"><div><label for="dashboard-band">Tu punto de partida</label><select id="dashboard-band"><option value="">Ver todas las edades</option>${stages.map(s=>`<option value="${s.id}" ${band===s.id?'selected':''}>${s.label}</option>`).join('')}</select></div><div>${pick?`<p>${pick.type==='guide'?'Para el adulto · juego fuera de pantalla':'Una propuesta de esta etapa'}</p><button type="button" class="action primary" data-dashboard-route="${pick.key}">${activityTitle(pick)}</button>`:'<p>Elige una franja para ver una propuesta inicial. Puedes explorar cualquier área.</p>'}</div></div><p class="quiet">La propuesta inicial depende de la franja elegida y de lo disponible, no de tus respuestas. Puedes cambiar «Tu punto de partida» libremente; no asigna un nivel ni borra tus elecciones.</p><p class="quiet dashboard-scope">${['18m','2y'].includes(band)?'El adulto consulta y aparta la pantalla. Los retos de otras edades aparecen identificados para no confundirlos con esta guía.':'Edades orientativas y propuestas piloto. No es un currículo completo ni un recorrido obligatorio.'}</p>${studioMarkup()}<div class="dashboard-columns"><section aria-labelledby="dashboard-areas"><h2 id="dashboard-areas" tabindex="-1">Todas las áreas</h2><div class="dashboard-area-grid">${areas.map((a,i)=>{const rows=catalog.filter(r=>r.area===a);return `<button type="button" class="dashboard-card" data-dashboard-area="${a}">${icon(i)}<strong>${a}</strong><span>${rows.length} ${rows.length===1?'propuesta disponible':'propuestas disponibles'}</span></button>`;}).join('')}</div></section><section aria-labelledby="dashboard-languages"><h2 id="dashboard-languages" tabindex="-1">Idiomas para escuchar y explorar</h2><p>6–8 años · con adulto · dos recorridos de tres palabras por idioma.</p><div class="dashboard-language-grid">${languages.map(l=>`<div class="dashboard-language-pair"><button type="button" class="dashboard-card" data-dashboard-route="5y:language-${l.id}"><span lang="${l.id}" class="dashboard-native">${l.native}</span><strong>${l.name}</strong><span>1 · Palabras cercanas</span></button><button type="button" class="action secondary" data-dashboard-route="5y:context-${l.id}">2 · Una cesta de palabras · ${l.name}</button></div>`).join('')}</div><p class="quiet">Voz sintética opcional: solo si hay una voz local del idioma. Si no existe, se puede jugar sin audio.</p></section></div><section id="dashboard-results" aria-live="off"></section><section aria-labelledby="dashboard-disciplines"><h2 id="dashboard-disciplines" tabindex="-1">Materias y conexiones</h2><p>Accesos a actividades existentes; cada ruta explica su alcance.</p><div class="dashboard-discipline-grid">${disciplines.map((d,i)=>`<button type="button" class="dashboard-card" data-dashboard-discipline="${d.id}">${icon(i===0||i===1||i===2?2:i===5?5:4)}<strong>${d.name}</strong><span>${d.status}</span></button>`).join('')}</div></section><section aria-labelledby="dashboard-tools"><h2 id="dashboard-tools" tabindex="-1">A tu lado</h2><div class="dashboard-tool-grid"><button type="button" class="dashboard-card" data-dashboard-utility="companion">${icon(5)}<strong>Luma · acompañante</strong><span>Pistas y apariencia opcionales</span></button><button type="button" class="dashboard-card" data-dashboard-utility="progress">${icon(6)}<strong>Progreso y privacidad</strong><span>Guardado en este navegador</span></button><button type="button" class="dashboard-card" data-dashboard-utility="family">${icon(0)}<strong>Orientación familiar</strong><span>Cómo acompañar y cuándo parar</span></button></div></section></section>`;
}
export function bindDashboard(root,{band,onBand,launch,openDestination}){
 const dash=root.querySelector('.dashboard');if(!dash)return;
 const results=dash.querySelector('#dashboard-results');
 const showRows=(title,rows)=>{const preferred=rows.filter(a=>a.stage===band),others=rows.filter(a=>a.stage!==band),ordered=[...preferred,...others];results.innerHTML=`<h2 tabindex="-1" id="dashboard-results-title">${title}</h2><p>${band?(preferred.length?'Primero, las propuestas de tu franja; después, otras edades señaladas.':'No hay una propuesta específica de esta franja. Estas son las opciones de otras edades.'):'Cada propuesta indica su edad orientativa y acompañamiento.'}</p><div class="dashboard-result-grid">${ordered.map(a=>`<button type="button" class="dashboard-card" data-dashboard-result="${a.key}"><strong>${activityTitle(a)}</strong><span>${age(a)}</span><span>${a.type==='guide'?'Guía de adulto · fuera de pantalla':a.id==='quantity'?'Ayuda adulta opcional':a.stage==='3y'||a.stage==='5y'?'Con adulto acompañante':'Apoyo disponible'} · disponible</span></button>`).join('')}</div>`;results.querySelectorAll('[data-dashboard-result]').forEach(b=>b.onclick=()=>launch(b.dataset.dashboardResult));results.querySelector('h2').focus();results.scrollIntoView?.({block:'start'});};
 dash.querySelector('#dashboard-band').onchange=e=>onBand(e.target.value);
 dash.querySelectorAll('[data-dashboard-route]').forEach(b=>b.onclick=()=>launch(b.dataset.dashboardRoute));
 dash.querySelectorAll('[data-dashboard-area]').forEach(b=>b.onclick=()=>showRows(b.dataset.dashboardArea,catalog.filter(a=>a.area===b.dataset.dashboardArea)));
 dash.querySelectorAll('[data-dashboard-games]').forEach(b=>b.onclick=()=>showRows('Juegos y retos disponibles',catalog.filter(a=>a.type==='digital')));
 dash.querySelectorAll('[data-dashboard-jump]').forEach(b=>b.onclick=()=>{const target=dash.querySelector('#'+b.dataset.dashboardJump);target.focus();target.scrollIntoView?.({block:'start'});});
 dash.querySelectorAll('[data-dashboard-discipline]').forEach(b=>b.onclick=()=>openDestination('discipline-'+b.dataset.dashboardDiscipline));
 dash.querySelectorAll('[data-dashboard-utility]').forEach(b=>b.onclick=()=>openDestination(b.dataset.dashboardUtility));
}
